import { DigitalItem, LineItemMap, PhysicalItem } from '@bigcommerce/checkout-sdk';
import React, { ReactNode } from 'react';
import { connect } from 'react-redux';

import { TranslatedString } from '@bigcommerce/checkout/locale';
import { useCheckout } from '@bigcommerce/checkout/payment-integration-api';

import { ProductList } from '../b3checkout/utils/quotes';
import { IconChevronDown, IconChevronUp } from '../ui/icon';
import { isSmallScreen } from '../ui/responsive';

import getItemsCount from './getItemsCount';
import mapFromCustom from './mapFromCustom';
import mapFromDigital from './mapFromDigital';
import mapFromGiftCertificate from './mapFromGiftCertificate';
import mapFromPhysical from './mapFromPhysical';
import OrderSummaryItem from './OrderSummaryItem';

const BackorderToggle = ({
    checked,
    onChange,
}: {
    checked: boolean;
    onChange: () => void;
}) => {
    const { checkoutState } = useCheckout();
    const inventorySettings = checkoutState.data.getConfig()?.inventorySettings;

    if (!inventorySettings?.shouldDisplayBackorderMessagesOnStorefront) {
        return null;
    }

    if (
        !inventorySettings.showQuantityOnHand &&
        !inventorySettings.showQuantityOnBackorder &&
        !inventorySettings.showBackorderMessage
    ) {
        return null;
    }

    return (
        <label className="cart-section-heading backorder-toggle-label optimizedCheckout-contentPrimary">
            Backorder details
            <input
                checked={checked}
                className="backorder-toggle-input"
                data-test="backorder-toggle"
                onChange={onChange}
                type="checkbox"
            />
            <span className="backorder-toggle-switch" />
        </label>
    );
};

const COLLAPSED_ITEMS_LIMIT = 4;
const COLLAPSED_ITEMS_LIMIT_SMALL_SCREEN = 3;

export interface OrderSummaryItemsProps {
    productList?: ProductList[];
    displayLineItemsCount: boolean;
    items: LineItemMap;
    invoiceVersion?: number;
    isBackorderDetailsEnabled?: boolean;
}

interface OrderSummaryItemsState {
    isExpanded: boolean;
    collapsedLimit: number;
    showBackorderDetails: boolean;
}

export class OrderSummaryItems extends React.Component<OrderSummaryItemsProps, OrderSummaryItemsState> {
    constructor(props: OrderSummaryItemsProps) {
        super(props);

        this.state = {
            isExpanded: false,
            collapsedLimit: this.getCollapsedLimit(),
            showBackorderDetails: false,
        };
    }

    mapNames = (productList: undefined | any[], cartItems: LineItemMap) => {
        function mapper<T extends {productId: number, variantId: number, name: string}>(item: T){
            const product = productList?.find((product: { productId: number; variantId: number; }) => product.productId === item.productId && product.variantId === item.variantId);

            if (product) {
                return {
                    ...item,
                    name: product.productName !== '' ? product.productName as string : item.name,
                }
            }

            return item;
        }

        const newItems = {
            physicalItems: cartItems.physicalItems.map(mapper<PhysicalItem>),
            digitalItems: cartItems.digitalItems.map(mapper<DigitalItem>),
            giftCertificates: cartItems.giftCertificates,
            customItems: cartItems.customItems,
        }

        return newItems
    }

    render(): ReactNode {
        const { displayLineItemsCount = true, items: cartItems, productList, isBackorderDetailsEnabled } = this.props;
        const { collapsedLimit, isExpanded, showBackorderDetails } = this.state;
        // const productList = storage.productList.getValue();
        let items = cartItems;

        try {
            if (productList) {
                items = this.mapNames(productList, cartItems);
            }

        } catch(error) {}

        const mappedItems = [
            ...items.physicalItems
                .slice()
                .sort((item) => item.variantId)
                .map(mapFromPhysical),
            ...items.giftCertificates.slice().map(mapFromGiftCertificate),
            ...items.digitalItems
                .slice()
                .sort((item) => item.variantId)
                .map(mapFromDigital),
            ...(items.customItems || []).map(mapFromCustom),
        ];

        const hasBackorderData = mappedItems.some(
            (item) => (item.quantityBackordered ?? 0) > 0,
        );

        return (
            <>
                {displayLineItemsCount && (
                    <div className="cart-section-heading-row">
                        <h3
                            className="cart-section-heading optimizedCheckout-contentPrimary"
                            data-test="cart-count-total"
                        >
                            <TranslatedString
                                data={{ count: getItemsCount(items) }}
                                id="cart.item_count_text"
                            />
                        </h3>
                        {isBackorderDetailsEnabled && hasBackorderData && (
                            <BackorderToggle
                                checked={showBackorderDetails}
                                onChange={this.handleBackorderToggle}
                            />
                        )}
                    </div>
                )}

                <ul aria-live="polite" className="productList">
                    {mappedItems
                        .slice(0, isExpanded ? undefined : collapsedLimit)
                        .map((summaryItemProps) => (
                            <li className="productList-item is-visible" key={summaryItemProps.id}>
                                <OrderSummaryItem
                                    {...summaryItemProps}
                                    showBackorderDetails={showBackorderDetails}
                                />
                            </li>
                        ))}
                </ul>

                {this.renderActions()}
            </>
        );
    }

    private getCollapsedLimit(): number {
        return isSmallScreen() ? COLLAPSED_ITEMS_LIMIT_SMALL_SCREEN : COLLAPSED_ITEMS_LIMIT;
    }

    private renderActions(): ReactNode {
        const { isExpanded } = this.state;

        if (this.getLineItemCount() <= this.getCollapsedLimit()) {
            return;
        }

        return (
            <div className="cart-actions">
                <button
                    className="button button--tertiary button--tiny optimizedCheckout-buttonSecondary"
                    onClick={this.handleToggle}
                    type="button"
                >
                    {isExpanded ? (
                        <>
                            <TranslatedString id="cart.see_less_action" />
                            <IconChevronUp />
                        </>
                    ) : (
                        <>
                            <TranslatedString id="cart.see_all_action" />
                            <IconChevronDown />
                        </>
                    )}
                </button>
            </div>
        );
    }

    private getLineItemCount(): number {
        const { items } = this.props;

        return (
            (items.customItems || []).length +
            items.physicalItems.length +
            items.digitalItems.length +
            items.giftCertificates.length
        );
    }

    private handleToggle: () => void = () => {
        const { isExpanded } = this.state;

        this.setState({ isExpanded: !isExpanded });
    };

    private handleBackorderToggle: () => void = () => {
        const { showBackorderDetails } = this.state;

        this.setState({ showBackorderDetails: !showBackorderDetails });
    };
}

const mapStateToProps = (state: { global: { productList: ProductList[] } }) => {
    const {
        global: {
            productList
        },
    } = state

    return {
        productList
    }
}

export default connect(mapStateToProps, {})(OrderSummaryItems)
